/* ===== variedad (10-11-2026): cada partida saca su mezcla de personas, incidentes, origen del público, accesos del coche, hora y afluencia.
   Todo sale de la semilla: la misma semilla da la misma partida, y lo correcto siempre funciona (sin dados en los resultados). ===== */
function mul(seed){ let a=seed>>>0; return function(){ a=(a+0x6D2B79F5)|0; let t=Math.imul(a^(a>>>15),1|a); t=(t+Math.imul(t^(t>>>7),61|t))^t; return ((t^(t>>>14))>>>0)/4294967296; }; }
function shuf(a,r){ a=a.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.floor(r()*(i+1)); const t=a[i]; a[i]=a[j]; a[j]=t; } return a; }
function nfmt(n){ return n>=1000?Math.floor(n/1000)+L('.',',')+String(n%1000).padStart(3,'0'):String(n); }
