function busDraw(seed){ const r=mul((seed^0x27d4eb2f)>>>0); const rs=r()<0.5?'A':'B', ot=rs==='A'?'B':'A';
  const nat={}; nat[rs]=r()<0.5?'risk':'riv'; nat[ot]=r()<0.6?'fest':'calm'; nat.C=r()<0.55?'arr':'arrv';
  const ev=[]; BSLOT.forEach(sl=>{ let pools=sl.k==='C'?(nat.C==='arrv'?['arr','arrv']:['arr']):sl.k?[nat[sl.k]==='calm'?'fest':nat[sl.k]]:['mid'];
    const cand=BEV.filter(e=>e.pool.some(p=>pools.indexOf(p)>=0)&&ev.indexOf(e.id)<0); ev.push(cand[Math.floor(r()*cand.length)].id); });
  return {rs,nat,ev}; }
function busKeys(d){ return d.ev.map(x=>'e:'+x).concat(['n:'+d.rs+d.nat[d.rs]+d.nat.C]); }
function newBus(seed){ const M=C.MAPS.bernabeu; const d=busDraw(seed); G={mi:'bus',seed,M,mapKey:'bernabeu',rs:d.rs,nat:d.nat,evIds:d.ev,keys:busKeys(d),phase:'plan',apr:G&&G.apr||false,pos:[null,null,null,null],spd:null,log:[],dec:[],bs:0,ev:0,stopAt:null,delay:0,hits:0,ten:0,force:0,fb:null,pulse:null,wait:false,fx:[]};
  G.route=routeInit(M.r); G.clock=()=>clk(19*60+15+G.bs/G.route.len*12+G.delay); return G; }
