  G.fb={cls:o.ok===2?'g':o.ok?'p':'b',b:(o.ok===2?'✓ ':o.ok?'~ ':'✗ ')+L(o.es,o.en),t:L(o.why[0],o.why[1])}; lg(L(o.why[0],o.why[1]),null,o.ok===2?'good':'bad');
