function drawBusM(g,px){ const RL=G.route.len;
  Object.keys(SPOT).forEach(k=>{ const S=SPOT[k]; const nt=G.nat[k]; const fans=blob(0,0,k==='C'?70:nt==='risk'?26:nt==='riv'?30:nt==='calm'?12:40,1,1,k.charCodeAt(0));
    fans.forEach((f,i)=>{ const side=k==='C'?(i%2?1:-1):S.side; const ss=S.s-30+(f[0]+1)*30; const off=side*(7.5+Math.abs(f[1])*9); const p=rOff(ss,off); dot(g,p[0],p[1],Math.max(1.0,2.4*px),(nt==='risk'&&i%3===0)||nt==='riv'||(nt==='arrv'&&i%4===0)?'#ff8a73':'#e9dcae'); });
    const us=at(k); us.forEach((ui,j)=>{ const u=UNITS[ui]; const side=k==='C'?(j%2?-1:1):S.side; for(let m=0;m<(u.k==='cab'?4:8);m++){ const p=rOff(S.s-16+m*(u.k==='cab'?7:4.2)+j*2,side*5.6); if(u.k==='cab'){ g.save(); g.translate(p[0],p[1]); g.rotate(p[2]); g.fillStyle='#8a5a2b'; g.beginPath(); g.ellipse(0,0,2.4,1.1,0,0,Math.PI*2); g.fill(); g.fillStyle='#4ea1ff'; g.beginPath(); g.arc(0.2,0,0.6,0,7); g.fill(); g.restore(); } else { dot(g,p[0],p[1],Math.max(1.1,2.6*px),'#4ea1ff'); g.strokeStyle='#cfe3ff'; g.lineWidth=Math.max(0.3,0.9*px); g.beginPath(); g.moveTo(p[0]-Math.cos(p[2])*1.2-Math.sin(p[2])*side*1.2,p[1]-Math.sin(p[2])*1.2+Math.cos(p[2])*side*1.2); g.lineTo(p[0]+Math.cos(p[2])*1.2-Math.sin(p[2])*side*1.2,p[1]+Math.sin(p[2])*1.2+Math.cos(p[2])*side*1.2); g.stroke(); } } });
    const lp=rOff(S.s,S.side*(k==='C'?-22:-20)); if(G.phase==='plan'||G.phase==='end'){ dot(g,lp[0],lp[1],12*px,'rgba(232,197,71,.9)'); label(g,lp[0],lp[1],k,px,'#2a2410',12); } });
  if(G.phase==='plan'){ label(g,575,300,L('Estadio','Stadium'),px,'#e8c547',11,'rgba(20,22,26,.8)'); const st=rAt(0); label(g,st[0]+40,st[1]-14,L('Salida','Start'),px,'#fff',11,'rgba(20,22,26,.8)'); }
  /* autobús + motos */ const p=rAt(G.bs); const h=p[2]; [[16,-1.4],[16,1.4],[-9,0]].forEach(o=>{ const q=[p[0]+Math.cos(h)*o[0]-Math.sin(h)*o[1],p[1]+Math.sin(h)*o[0]+Math.cos(h)*o[1]]; dot(g,q[0],q[1],0.9+0.5*px,'#e9f1ff'); });
  g.save(); g.translate(p[0],p[1]); g.rotate(h); g.fillStyle='#0d0f12'; g.fillRect(-11.6,-1.9,13.2,3.8); g.fillStyle='#f2f4f7'; g.fillRect(-11,-1.3,12,2.6); g.fillStyle='#3d6fb6'; g.fillRect(-11,-0.35,12,0.7); g.fillStyle='#22262c'; g.fillRect(-0.6,-1.2,1.4,2.4); g.restore();
  G.fx.forEach(f=>{ const a=(performance.now()-f.t)/1000; if(a<1.5){ const q=rAt(f.s); dot(g,q[0],q[1],(3+a*6)*px,'rgba(255,138,115,'+(1-a/1.5)+')'); } });
  if(G.pulse){ pulse(g,G.pulse[0],G.pulse[1],px); const E=G.phase==='ev'&&busEvents()[G.ev]; if(E){ const nm=L(E.nm[0],E.nm[1]); label(g,G.pulse[0],G.pulse[1]-30*px,nm,px,'#fff',11,'rgba(20,22,26,.85)'); } } }

/* ================= interfaz ================= */
function medal(sc){ if(G.apr) return; try{ window.MAT_MED&&window.MAT_MED.event('ad.fin',{sc,d:'mi'}); }catch(_){} }
function objTxt(){ return G.mi==='bus'?L('Eres el mando del dispositivo. Objetivo: que el autobús del equipo local llegue al estadio a su hora (19:27), sin ningún impacto y sin cargas innecesarias. Primero colocas tus unidades con la información previa; luego, en ruta, decides qué hacer en cada incidente.','You command the operation. Goal: get the home team bus to the stadium on time (19:27), with no hits and no needless charges. First you place your units using the prior intelligence; then, on the way, you decide what to do at each incident.')
  :L('Eres el jefe del dispositivo de la UIP. A las '+hm(0)+' llega una alta autoridad a un acto en la Plaza Mayor. Tres fases: 1) cierras el perímetro y eliges accesos; 2) llevas un control de acceso, persona a persona; 3) resuelves los incidentes de la llegada.','You lead the UIP operation. At '+hm(0)+' a dignitary arrives for a ceremony in the Plaza Mayor. Three phases: 1) close the perimeter and choose entrances; 2) run an access checkpoint, person by person; 3) handle the incidents on arrival.'); }
function steps(){ const S=G.mi==='bus'?[['plan',L('1 Plan','1 Plan')],['drive',L('2 En ruta','2 En route')],['end',L('3 Balance','3 Debrief')]]:[['plan',L('1 Perímetro','1 Perimeter')],['chk',L('2 Control','2 Checks')],['arr',L('3 Llegada','3 Arrival')],['end',L('Balance','Debrief')]];
  const ph=G.phase==='ev'?'drive':G.phase; const k=S.findIndex(s=>s[0]===ph); return '<div class="mi-step">'+S.map((s,i)=>'<span class="'+(i===k?'on':i<k?'ok':'')+'">'+(i<k?'✓ ':'')+s[1]+'</span>').join('')+'</div>'; }
function bar(v,max){ const f=Math.max(0,Math.min(1,v/max)); return '<span class="mi-bar'+(f>0.8?' r':f>0.5?' w':'')+'"><i style="width:'+Math.round(f*100)+'%"></i></span>'; }
function hudHTML(){ if(G.mi==='bus'){ return '<span>🕒 <b>'+G.clock()+'</b></span><span>'+L('Retraso','Delay')+' <b>'+(G.delay?'+'+G.delay+' min':'0')+'</b></span><span>'+L('Impactos','Hits')+' <b>'+G.hits+'</b></span><span>'+L('Tensión','Tension')+' '+bar(G.ten,4)+'</span><span>'+L('Cargas','Charges')+' <b>'+G.force+'</b></span>'; }
  if(G.phase==='plan'){ const c=planCheck(); return '<span>'+L('Controles','Checkpoints')+' <b>'+c.nC+'/3</b></span><span>'+L('Autoridad','Dignitary')+' <b>'+c.nA+'/1</b></span><span>'+L('Cerrados','Closed')+' <b>'+(10-c.nC-c.nA)+'</b></span>'; }
  if(G.phase==='chk') return '<span>🕒 <b>'+G.clock()+'</b> '+L('(cierre '+hm(-5)+')','(closes '+hm(-5)+')')+'</span><span>'+L('Cola','Queue')+' '+bar(waiting(),6)+' <b>'+waiting()+'</b></span><span>'+L('Atendidos','Done')+' <b>'+G.pi+'/'+G.ord.length+'</b></span>';
  return '<span>🕒 <b>'+G.clock()+'</b></span><span>'+L('Dentro de la plaza','Inside the square')+' <b>~'+nfmt(G.crowd)+'</b></span>'; }
function shell(){ C.page('<div class="mi" id="mi"><h2 style="margin:6px 0 2px">'+(G.mi==='bus'?L('Escolta del autobús del equipo','Team bus escort'):L('Visita oficial','Official visit'))+'</h2><p class="ad-note" style="margin:0 0 4px">'+(G.mi==='bus'?L('Madrid · Paseo de la Castellana → Avenida de Concha Espina (estadio Santiago Bernabéu). Ruta plausible, no la oficial.','Madrid · Paseo de la Castellana → Avenida de Concha Espina (Santiago Bernabéu stadium). Plausible route, not the official one.'):L('Madrid · Plaza Mayor (calles reales de OpenStreetMap).','Madrid · Plaza Mayor (real streets from OpenStreetMap).'))+'</p><div class="ad-obj">'+objTxt()+'</div><div id="mi-st"></div><div id="mi-hud" class="mi-hud"></div><div class="mi-cv" id="mi-cvw"><canvas id="mi-cv"></canvas></div>'+legend()+'<div id="mi-ctl"></div><ul class="mi-log" id="mi-log"></ul>'+datos()+'</div>');
  CV=document.getElementById('mi-cv'); CTX=CV.getContext('2d'); CV.addEventListener('click',onCanvas); fit(); }
function legend(){ return '<div class="mi-leg">'+(G.mi==='bus'?'<span style="--c:#e9dcae">'+L('Aficionados','Fans')+'</span><span style="--c:#ff8a73">'+L('Grupo de riesgo','Risk group')+'</span><span style="--c:#4ea1ff">UIP</span><span style="--c:#8a5a2b">'+L('Caballería','Mounted')+'</span><span style="--c:#f2f4f7">'+L('Autobús y motos','Bus and motorcycles')+'</span>':'<span style="--c:#4ea1ff">'+L('Control de acceso','Checkpoint')+'</span><span style="--c:#8d939b">'+L('Cerrado (vallas + pareja)','Closed (barriers + pair)')+'</span><span style="--c:#e8c547">'+L('Autoridad','Dignitary')+'</span><span style="--c:#e9dcae">'+L('Público','Public')+'</span>')+'</div>'; }
function aprBtn(){ return '<div class="ad-seg" style="margin:6px 0"><button type="button" data-mx="apr0" class="'+(G.apr?'':'on')+'">'+L('Normal','Normal')+'</button><button type="button" data-mx="apr1" class="'+(G.apr?'on':'')+'">'+L('Aprende (te dice qué haría un mando)','Learn (shows what a commander would do)')+'</button></div>'; }
function fbHTML(){ const f=G.fb; return f?'<div class="mi-fb '+f.cls+'"><b>'+esc(f.b)+'</b>'+esc(f.t)+'</div>':''; }
function optsHTML(E,kind){ const best=Math.max(...E.o.filter(o=>!o.dis).map(o=>o.ok)); const bi=E.o.findIndex(o=>!o.dis&&o.ok===best);
  return '<div class="mi-intel"><b>'+(E.time?E.time+' · ':'')+L('¿Qué ordenas?','Your order?')+'</b>'+esc(E.t)+'</div>'+(G.apr?'<p class="mi-apr">★ '+L('Aprende: la opción marcada es la que haría un mando.','Learn: the marked option is what a commander would do.')+'</p>':'')+'<div class="mi-opts">'+E.o.map((o,i)=>'<button type="button" class="ad-btn'+(G.apr&&i===bi?' rec':'')+'" data-mx="'+kind+i+'"'+(o.dis?' disabled':'')+'>'+(G.apr&&i===bi?'★ ':'')+esc(L(o.es,o.en))+(o.dis?' <small>('+L('no disponible: no pusiste a nadie ahí','not available: you put nobody there')+')</small>':'')+'</button>').join('')+'</div>'; }
function contBtn(t){ return '<div class="mi-row"><button type="button" class="ad-btn" data-mx="cont">'+(t||L('Continuar ▸','Continue ▸'))+'</button></div>'; }
function recAct(c){ const p=c.p; if(p.opts) return 'L'+bestOpt(p).id; for(const n of p.need){ if(c.did.indexOf(n)<0) return n; } return 'F'+p.fin; }
function personCanvas(p){ return '<canvas id="mi-pc" width="152" height="208" data-col="'+p.col+'" data-bag="'+(p.bag||'')+'"></canvas>'; }
function paintPerson(){ const c=document.getElementById('mi-pc'); if(!c) return; const g=c.getContext('2d'); g.setTransform(2,0,0,2,0,0); g.clearRect(0,0,76,104); const col=c.dataset.col, bag=c.dataset.bag;
  g.fillStyle='#3a4048'; g.fillRect(0,86,76,18); g.fillStyle=col; g.beginPath(); g.moveTo(22,88); g.lineTo(26,48); g.quadraticCurveTo(38,40,50,48); g.lineTo(54,88); g.closePath(); g.fill(); g.fillStyle='#d9b99b'; g.beginPath(); g.arc(38,32,10,0,Math.PI*2); g.fill(); g.fillStyle='#2d2a26'; g.beginPath(); g.arc(38,28,10.5,Math.PI,0); g.fill();
  g.fillStyle='#2a2d33'; g.fillRect(28,86,8,10); g.fillRect(40,86,8,10);
  if(bag==='mochila'||bag==='camara'){ g.fillStyle=bag==='camara'?'#1f2227':'#5a4632'; g.fillRect(52,52,12,24); g.fillStyle='rgba(255,255,255,.15)'; g.fillRect(54,58,8,3); }
  if(bag==='bolso'){ g.fillStyle='#7a3f2e'; g.fillRect(52,64,14,12); g.strokeStyle='#7a3f2e'; g.lineWidth=1.5; g.beginPath(); g.arc(59,64,5,Math.PI,0); g.stroke(); }
  if(bag==='carrito'){ g.strokeStyle='#cfd5dc'; g.lineWidth=1.5; g.beginPath(); g.moveTo(56,60); g.lineTo(60,82); g.stroke(); g.fillStyle='#4b6b8c'; g.fillRect(58,66,16,12); g.fillStyle='#111'; g.beginPath(); g.arc(61,84,2.5,0,7); g.arc(71,84,2.5,0,7); g.fill(); }
  if(bag==='maleta'){ g.fillStyle='#3e5a78'; g.fillRect(54,62,16,24); g.strokeStyle='#cfd5dc'; g.lineWidth=1.5; g.beginPath(); g.moveTo(58,62); g.lineTo(58,52); g.lineTo(66,52); g.lineTo(66,62); g.stroke(); g.fillStyle='#111'; g.beginPath(); g.arc(57,88,2,0,7); g.arc(67,88,2,0,7); g.fill(); }
  if(bag==='funda'){ g.fillStyle='#262a30'; g.beginPath(); g.ellipse(60,70,7,14,0.15,0,7); g.fill(); g.fillRect(57,30,6,28); }
  if(bag==='cartel'){ g.fillStyle='#c9a77a'; g.fillRect(8,50,30,20); g.fillStyle='#5a3d22'; g.fillRect(11,57,24,3); }
  if(bag==='silla'){ g.strokeStyle='#9aa3ad'; g.lineWidth=2; g.beginPath(); g.arc(30,88,13,0,7); g.stroke(); g.beginPath(); g.moveTo(20,60); g.lineTo(20,80); g.lineTo(52,80); g.stroke(); g.fillStyle='#7a3f2e'; g.fillRect(12,64,10,10); }
  if(bag==='mastil'){ g.strokeStyle='#a07a4a'; g.lineWidth=2; g.beginPath(); g.moveTo(58,90); g.lineTo(58,8); g.stroke(); g.fillStyle='#3d7a8c'; g.fillRect(58,8,16,11); g.fillStyle='#e6e0c8'; g.fillRect(58,12,16,3); } }
function visPanel(){ let h='';
  if(G.phase==='plan'){ const c=planCheck(); h+=aprBtn()+'<div class="mi-intel"><b>'+L('Información previa','Prior intelligence')+'</b>'+esc(L('Se esperan unas '+nfmt(G.crowd)+' personas. ','About '+nfmt(G.crowd)+' people are expected. ')+L(G.F.es,G.F.en))+' '+esc(vehTxt())+' '+L('Tienes 3 equipos de control (arco detector y revisión de bolsos); los demás accesos se cierran con vallas y una pareja de agentes.','You have 3 checkpoint teams (walk-through detector and bag search); the other entrances are closed with barriers and a pair of officers.')+'</div>';
    h+='<p class="mi-tip">'+L('Toca cada acceso (en el mapa o aquí) para cambiarlo: cerrado → control → autoridad (solo '+G.veh.map(i=>i+1).join(' y ')+').','Tap each entrance (on the map or here) to change it: closed → checkpoint → dignitary (only '+G.veh.map(i=>i+1).join(' and ')+').')+'</p><div class="mi-tiles">'+G.E.map((v,i)=>'<button type="button" class="mi-tile '+(v==='c'?'c':v==='a'?'a':'')+'" data-mx="e'+i+'">'+(v==='a'?'★ ':'')+(i+1)+'<small>'+(v==='c'?L('control','check'):v==='a'?L('autoridad','dignitary'):L('cerrado','closed'))+'</small></button>').join('')+'</div>';
    if(G.apr){ h+='<p class="mi-apr">★ '+L('Aprende: los controles van donde llega la gente (más cerca de la flecha) y la autoridad entra por el acceso de coche que quede lejos de esas colas.','Learn: checkpoints go where people arrive (nearest the arrow) and the dignitary uses the car entrance far from those queues.')+'</p>'; }
    h+='<div class="mi-row"><button type="button" class="ad-btn" data-mx="go"'+(c.ok?'':' disabled')+'>'+(c.ok?L('Abrir los controles ('+hm(-30)+') ▸','Open the checkpoints ('+hm(-30)+') ▸'):L('Faltan: ','Missing: ')+(c.nC!==3?(c.nC<3?(3-c.nC)+L(' control(es)',' checkpoint(s)'):L('sobran controles','too many checkpoints')):'')+(c.nA!==1?(c.nC!==3?' · ':'')+L('entrada de la autoridad','dignitary entrance'):''))+'</button></div>'; }
  else if(G.phase==='chk'){ const c=G.cur; if(!c) return fbHTML(); const p=c.p; const rec=G.apr?recAct(c):'';
    h+=fbHTML()+'<div class="mi-intel"><b>'+L('Protocolo de tu control','Your checkpoint\'s rules')+'</b>'+L('Todos pasan por el arco · todos los bolsos se revisan · si pita: vaciar bolsillos y repetir · cacheo solo con indicios · prohibidos: armas, pirotecnia, sprays, cristal, punteros láser, mástiles y palos rígidos, drones (armas: no entra; lo demás se retiene) · marcapasos: ni arco ni detector, revisión a mano · silla de ruedas: detector de mano.','Everyone through the arch · every bag is searched · if it beeps: empty pockets and repeat · pat-down only with grounds · banned: weapons, pyrotechnics, sprays, glass, laser pointers, rigid poles and sticks, drones (weapons: refused; the rest is kept) · pacemaker: no arch or detector, hand check · wheelchair: hand-held detector.')+'</div>';
    h+='<div class="mi-card2">'+personCanvas(p)+'<div><h4>'+(c.n+1)+'/'+G.ord.length+' · '+esc(L(p.d[0],p.d[1]))+'</h4>'+(p.say?'<q>'+esc(L(p.say[0],p.say[1]))+'</q>':'')+'<ul>'+(p.cl||[]).map(x=>'<li>'+esc(L(x[0],x[1]))+'</li>').join('')+c.did.map(k=>'<li><b>'+esc(L(ACT[k][1],ACT[k][2]))+':</b> '+esc(actRes(c,k))+'</li>').join('')+'</ul></div></div>';
    if(p.opts){ h+=(G.apr?'<p class="mi-apr">★ '+L('Aprende: la opción marcada es la que haría un mando.','Learn: the marked option is what a commander would do.')+'</p>':'')+'<div class="mi-opts">'+p.opts.map(o=>'<button type="button" class="ad-btn'+(G.apr&&o.ok===2?' rec':'')+'" data-mx="L'+o.id+'">'+(G.apr&&o.ok===2?'★ ':'')+esc(L(o.es,o.en))+'</button>').join('')+'</div>'; }
    else { const done=k=>c.did.indexOf(k)>=0; const arcoB=done('arco')&&(p.arco==='beep'||p.arco==='beep2');
      const en={arco:!done('arco'),rep:arcoB&&!done('rep'),bolso:!!p.bag&&p.bag!=='mastil'&&p.bag!=='cartel'&&!done('bolso'),wand:!done('wand')&&(done('arco')||p.arco==='pm'||p.arco==='wc'),cacheo:!done('cacheo'),radio:false};
      h+='<div class="mi-acts">'+['arco','rep','bolso','wand','cacheo'].map(k=>'<button type="button" class="ad-btn'+(rec===k?' rec':'')+'" data-mx="A'+k+'"'+(en[k]?'':' disabled')+'>'+(rec===k?'★ ':'')+L(ACT[k][1],ACT[k][2])+'<small>'+ACT[k][0]+' s · '+L(ACT[k][3],ACT[k][4])+'</small></button>').join('')+
        ['in','keep','out'].map(k=>'<button type="button" class="ad-btn '+(k==='out'?'no':'fin')+(rec==='F'+k?' rec':'')+'" data-mx="F'+k+'"'+(k==='keep'&&!canKeep(c)?' disabled':'')+'>'+(rec==='F'+k?'★ ':'')+L(FIN[k][1],FIN[k][2])+'</button>').join('')+'</div>'; } }
  else if(G.phase==='arr'){ if(G.wait) h+=fbHTML()+contBtn(G.ev>=3?L('Ver el balance ▸','See the debrief ▸'):null); else if(G.ev===2&&G.vip&&G.vip.st!=='dais') h+='<p class="mi-tip">'+L('La autoridad camina con su escolta hasta la tribuna…','The dignitary walks with the protection team to the stage…')+'</p>'; else h+=optsHTML(visEvents()[G.ev],'V'); }
  return h; }
function actRes(c,k){ const p=c.p; if(k==='arco') return p.arco==='pm'||p.arco==='wc'?L('no debía','should not'):p.arco==='ok'?L('no pita','clear'):L('pita','beeps'); if(k==='rep') return (p.pk?L(p.pk[0],p.pk[1])+' ':'')+(p.arco==='beep'?L('ya no pita','clear now'):L('sigue pitando','still beeping')); if(k==='bolso') return L(p.bagC[0],p.bagC[1]); if(k==='wand') return p.arco==='pm'?L('no debía','should not'):p.wd?L(p.wd[0],p.wd[1]):L('nada','nothing'); if(k==='cacheo') return indicio(c)?(p.body?L(p.body[0],p.body[1]):L('nada','nothing')):L('sin indicios','no grounds'); return ''; }
function busPanel(){ let h='';
  if(G.phase==='plan'){ h+=aprBtn()+'<div class="mi-intel"><b>'+L('Información previa','Prior intelligence')+'</b>'+Object.keys(SPOT).map(k=>'<b style="display:inline">'+L(SPOT[k].es,SPOT[k].en)+' · '+L(NAT[G.nat[k]].es,NAT[G.nat[k]].en)+':</b> '+esc(L(NAT[G.nat[k]].i[0],NAT[G.nat[k]].i[1]))).join('<br>')+'<br>'+L('Las motos van siempre delante y detrás del autobús.','Motorcycles always ride ahead of and behind the bus.')+'</div>';
    h+='<p class="mi-tip">'+L('Coloca cada unidad en un punto antes de que salga el autobús. UIP: escudos (paran objetos) y cordones. Caballería: ve desde arriba y mantiene la calzada libre en avenidas; los objetos lanzados y el fuego asustan a los caballos.','Place each unit at a point before the bus leaves. UIP: shields (stop objects) and cordons. Mounted: sees from above and keeps the road clear on avenues; thrown objects and fire startle horses.')+'</p><div class="mi-units">'+UNITS.map((u,i)=>'<div class="r"><b>'+(u.k==='uip'?'🛡 ':'🐎 ')+L(u.es,u.en)+'</b><div class="ad-seg">'+['A','B','C'].map(k=>'<button type="button" data-mx="u'+i+k+'" class="'+(G.pos[i]===k?'on':'')+'">'+k+'</button>').join('')+'</div></div>').join('')+'</div>';
    h+='<p class="mi-tip" style="margin-top:8px"><b>'+L('Velocidad del convoy','Convoy speed')+'</b></p><div class="ad-seg">'+Object.keys(SPEED).map(k=>'<button type="button" data-mx="s'+k+'" class="'+(G.spd===k?'on':'')+'">'+L(SPEED[k][0],SPEED[k][1])+'</button>').join('')+'</div>';
    if(G.apr) h+='<p class="mi-apr">★ '+(G.nat.C==='arrv'?L('Aprende: una UIP en '+G.rs+' (hacen falta escudos), dos UIP en C (pasillo y separar a la afición visitante), la Caballería en el otro punto, y velocidad constante y moderada.','Learn: one UIP at '+G.rs+' (shields needed), two UIPs at C (corridor and keeping the away fans apart), the mounted unit at the other point, and a steady, moderate speed.'):L('Aprende: una UIP en '+G.rs+' (hacen falta escudos), dos unidades en C para el pasillo de llegada (al menos una UIP), la cuarta donde quieras, y velocidad constante y moderada.','Learn: one UIP at '+G.rs+' (shields needed), two units at C for the arrival corridor (at least one UIP), the fourth wherever you like, and a steady, moderate speed.'))+'</p>';
    const ok=busPlanOk(); h+='<div class="mi-row"><button type="button" class="ad-btn" data-mx="go"'+(ok?'':' disabled')+'>'+(ok?L('Salir con el autobús (19:15) ▸','Leave with the bus (19:15) ▸'):L('Coloca las 4 unidades y elige la velocidad','Place the 4 units and choose the speed'))+'</button></div>'; }
  else if(G.phase==='drive'){ h+=G.wait?fbHTML()+contBtn():'<p class="mi-tip">'+L('El autobús avanza con las motos…','The bus moves on with the motorcycles…')+'</p>'; }
  else if(G.phase==='ev'){ h+=optsHTML(busEvents()[G.ev],'B'); }
  return h; }
function resultHTML(){ const r=G.res; const grade=r.tot>=90?L('Excelente','Excellent'):r.tot>=70?L('Bien','Good'):r.tot>=50?L('Mejorable','Needs work'):L('Mal','Poor');
  const ic=o=>o===2?'✓':o===1?'~':'✗';
  return '<div class="mi-res"><div class="sc">'+r.tot+' / 100 · '+grade+'</div>'+(G.apr?'<p class="mi-apr">'+L('Partida en modo Aprende (no cuenta para medallas).','Played in Learn mode (does not count for medals).')+'</p>':'')+(G.breach?'<p style="color:#ffb3a6"><b>'+L('Fallo grave: entró un arma blanca en la plaza.','Serious failure: a knife got into the square.')+'</b></p>':'')+
    '<p>'+r.parts.map(p=>esc(p[0])+': <b>'+p[1]+'/'+p[2]+'</b>').join(' · ')+'</p><h3 style="margin:8px 0 2px;font-size:15px">'+L('Cada decisión, explicada','Every decision, explained')+'</h3><ul class="mi-deb">'+G.dec.map(d=>'<li><b>'+ic(d.ok)+'</b>'+esc(d.t)+' — <i>'+esc(d.r)+'</i> · '+d.pts+'/'+d.max+'<small>'+esc(d.why)+'</small></li>').join('')+'</ul><p class="ad-note">'+L('Puntuación: Estimación de M.A.T. Sin dados: con las mismas decisiones, la misma partida acaba igual.','Score: M.A.T estimate. No dice: the same decisions give the same result.')+'</p></div>'+
    '<div class="mi-row"><button type="button" class="ad-btn" data-mx="rep">'+L('Repetir esta partida','Replay this game')+'</button><button type="button" class="ad-btn" data-mx="new">'+L('Partida nueva','New game')+'</button><button type="button" class="ad-btn" data-mx="other">'+(G.mi==='bus'?L('Ir a «Visita oficial»','Go to «Official visit»'):L('Ir a «Escolta del autobús»','Go to «Team bus escort»'))+'</button><button type="button" class="ad-btn" data-mx="back">'+L('Volver a Antidisturbios','Back to Riot control')+'</button></div>'; }
function render(){ const st=document.getElementById('mi-st'); if(!st) return; st.innerHTML=steps(); document.getElementById('mi-hud').innerHTML=hudHTML();
  document.getElementById('mi-ctl').innerHTML=G.phase==='end'?resultHTML():(G.mi==='bus'?busPanel():visPanel()); paintPerson();
  document.getElementById('mi-log').innerHTML=G.log.slice(0,12).map(l=>'<li class="'+l.c+'"><time>'+l.t+'</time>'+esc(l.txt)+'</li>').join(''); draw(); }
function onCanvas(ev){ if(!G||G.mi!=='vis'||G.phase!=='plan') return; const r=CV.getBoundingClientRect(); const v=G.cv, B=G.cam||camBox(); const s=Math.min(v.cw/B[2],v.ch/B[3]); const ox=(v.cw-B[2]*s)/2-B[0]*s, oy=(v.ch-B[3]*s)/2-B[1]*s; const x=(ev.clientX-r.left-ox)/s, y=(ev.clientY-r.top-oy)/s;
  let bi=-1,bd=22/s; ENT_MAYOR.forEach((e,i)=>{ const d=Math.hypot(e.x-x,e.y-y); if(d<bd){ bd=d; bi=i; } }); if(bi>=0){ setE(bi); render(); } }
function onClick(e){ const t=e.target.closest('[data-mx]'); if(!t||!document.getElementById('mi')||!G) return; const a=t.dataset.mx;
  if(a==='apr0'||a==='apr1'){ G.apr=a==='apr1'; render(); return; }
  if(a==='rep'){ launch(G.mi,G.seed,G.apr); return; } if(a==='new'){ launch(G.mi,freshSeed(G.mi),G.apr); return; } if(a==='other'){ const m=G.mi==='bus'?'vis':'bus'; launch(m,freshSeed(m),G.apr); return; } if(a==='back'){ const b=C.back; G=null; if(RAF){ cancelAnimationFrame(RAF); RAF=0; } b(); return; }
  if(G.mi==='vis'){ if(G.phase==='plan'){ if(a[0]==='e'){ setE(+a.slice(1)); render(); return; } if(a==='go'&&planCheck().ok){ startChk(); render(); const s=document.getElementById('mi-st'); s&&s.scrollIntoView&&s.scrollIntoView({block:'start'}); return; } }
    else if(G.phase==='chk'){ if(a[0]==='A') doAct(a.slice(1)); else if(a[0]==='F') finish(a.slice(1)); else if(a[0]==='L') finish(a.slice(1)); render(); return; }
    else if(G.phase==='arr'){ if(a==='cont'){ visCont(); render(); return; } if(a[0]==='V'){ visChoose(+a.slice(1)); render(); return; } } }
  else { if(G.phase==='plan'){ if(a[0]==='u'){ const i=+a[1]; G.pos[i]=a[2]; render(); return; } if(a[0]==='s'){ G.spd=a.slice(1); render(); return; } if(a==='go'&&busPlanOk()){ busStart(); render(); const s=document.getElementById('mi-st'); s&&s.scrollIntoView&&s.scrollIntoView({block:'start'}); return; } }
    else if(G.phase==='ev'&&a[0]==='B'){ busChoose(+a.slice(1)); return; } else if(a==='cont'){ busCont(); return; } } }
function launch(mi,seed,apr){ if(RAF){ cancelAnimationFrame(RAF); RAF=0; } seed=(seed>>>0)||1; const keep=apr, rep=G&&G.mi===mi&&G.seed===seed; G=null; if(mi==='bus') newBus(seed); else newVis(seed); G.apr=!!keep; if(!rep) remember(mi,G.keys); G.cam=null; shell(); G.cam=camBox(); render(); window.scrollTo&&window.scrollTo(0,0); }
export function start(ctx){ C=ctx; if(!document.getElementById('micss2')){ const s=document.createElement('style'); s.id='micss2'; s.textContent=CSS; document.head.appendChild(s); }
  if(!BOUND){ BOUND=true; document.addEventListener('click',onClick); window.addEventListener('resize',()=>{ if(G&&CV&&document.getElementById('mi-cv')){ fit(); draw(); } }); }
  const mi=ctx.mi==='bus'?'bus':'vis'; launch(mi,ctx.seed||freshSeed(mi),false); }
/* hook de pruebas (solo lectura del estado + acciones como las del jugador) */
/* sin repetir: «Partida nueva» busca una semilla nueva al azar cuya mezcla se parezca lo menos posible a las 2 últimas partidas (guardadas en este navegador) */
function hist(){ try{ return JSON.parse(localStorage.getItem('mat_mi_hist')||'{}')||{}; }catch(e){ return {}; } }
function remember(mi,keys){ try{ const h=hist(); const a=(h[mi]||[]).filter(x=>Array.isArray(x)); a.unshift(keys); h[mi]=a.slice(0,2); localStorage.setItem('mat_mi_hist',JSON.stringify(h)); }catch(e){} }
function rnd32(){ try{ const u=new Uint32Array(1); crypto.getRandomValues(u); return u[0]||1; }catch(e){ return ((Date.now()*2654435761)^(Math.random()*4294967296))>>>0||1; } }
function freshSeed(mi){ const h=hist()[mi]||[]; const last=new Set(h[0]||[]), prev=new Set(h[1]||[]); let best=rnd32(), bs=1e9;
  for(let k=0;k<40;k++){ const s=rnd32(); const keys=mi==='bus'?busKeys(busDraw(s)):visKeys(visDraw(s)); const sc=keys.reduce((a,x)=>a+(last.has(x)?3:0)+(prev.has(x)?1:0),0); if(sc<bs){ bs=sc; best=s; } if(!sc) break; }
  return best; }
window.MAT_MI_TEST={st:()=>G,rec:()=>G&&G.cur?recAct(G.cur):null,best:()=>{ if(!G) return -1; const E=G.mi==='vis'?(G.phase==='arr'?visEvents()[G.ev]:null):(G.phase==='ev'?busEvents()[G.ev]:null); if(!E) return -1; const b=Math.max(...E.o.filter(o=>!o.dis).map(o=>o.ok)); return E.o.findIndex(o=>!o.dis&&o.ok===b); },worst:()=>{ const E=G.mi==='vis'?visEvents()[G.ev]:busEvents()[G.ev]; return E.o.findIndex(o=>!o.dis&&o.ok===0); },act:a=>{ const b=document.querySelector('[data-mx="'+a+'"]'); if(b&&!b.disabled){ b.click(); return true; } return false; },
  ideal:()=>G.mi==='vis'?visIdeal():busIdeal(),keys:()=>G.keys,draw:(mi,s)=>mi==='bus'?busKeys(busDraw(s)):visKeys(visDraw(s)),fresh:mi=>freshSeed(mi),pool:()=>({people:PEOPLE.length,inc:INC.length,bus:BEV.length}),
  sim:s=>{ const d=visDraw(s); return {ok:simOK(d.ids,PF[d.ci]),ci:d.ci,ids:d.ids.map(i=>PEOPLE[i].id)}; }};
